CustomField.formula:
if(  IsBlank(Retention_Products__c), "", "--Retention Products--"&BR()&
  if(  INCLUDES(Retention_Products__c, "R-Apollo Sales"), "Apollo Sales"&BR(), "")&
  if(  INCLUDES(Retention_Products__c, "R-Apollo Service"), "Apollo Service"&BR(), "")&
  if(  IsBlank(Retention_Products__c), "", BR())
)
&
if(  IsBlank(Website_Products__c), "", "--Website Products--"&BR()&
  if(  INCLUDES(Website_Products__c, "W-Apollo Sites"), "Apollo Sites"&BR(), "")&
  if(  INCLUDES(Website_Products__c, "W-Group Site"), "Group Site"&BR(), "")&
  if(  INCLUDES(Website_Products__c, "W-Apollo Assistant"), "Apollo Assistant"&BR(), "")&
  if(  INCLUDES(Website_Products__c, "W-Apollo Transact"), "Apollo Transact"&BR(), "")&
  if(  INCLUDES(Website_Products__c, "W-Credit PreQual"), "Credit PreQual"&BR(), "")&
  if(  INCLUDES(Website_Products__c, "W-Custom Creative"), "Custom Creative"&BR(), "")&
  if(  INCLUDES(Website_Products__c, "W-VDV"), "VDV"&BR(), "")&
  if(  INCLUDES(Website_Products__c, "W-SEO"), "SEO"&BR(), "")&
  if(  IsBlank(Website_Products__c), "", BR())
)
&
if(  IsBlank(Digital_Products__c), "", "--Digital Products--"&BR()&
  if(  INCLUDES(Digital_Products__c, "D-Apollo Ads (Sales)"), "Apollo Ads (Sales)"&BR(), "")&
  if(  INCLUDES(Digital_Products__c, "D-Apollo Ads (Service)"), "Apollo Ads (Service)"&BR(), "")&

  if(  INCLUDES(Digital_Products__c, "D-Search New") || INCLUDES(Digital_Products__c, "D-Search Pre-Owned") || INCLUDES(Digital_Products__c, "D-Search Service"), 
    "Search "&
	if(INCLUDES(Digital_Products__c, "D-Search New"), "New ", "")&
	if(INCLUDES(Digital_Products__c, "D-Search Pre-Owned"),"Pre-Owned ", "")&
	if(INCLUDES(Digital_Products__c, "D-Search Service"), "Service", "")
	&BR(), ""
  )&

  if(  INCLUDES(Digital_Products__c, "D-Display New") || INCLUDES(Digital_Products__c, "D-Display Pre-Owned") || INCLUDES(Digital_Products__c, "D-Display Service"), 
    "Display "&
	if(INCLUDES(Digital_Products__c, "D-Display New"), "New ", "")&
	if(INCLUDES(Digital_Products__c, "D-Display Pre-Owned"),"Pre-Owned ", "")&
	if(INCLUDES(Digital_Products__c, "D-Display Service"), "Service", "")
	&BR(), ""
  )&

  if(  INCLUDES(Digital_Products__c, "D-Social New") || INCLUDES(Digital_Products__c, "D-Social Pre-Owned") || INCLUDES(Digital_Products__c, "D-Social Service"), 
    "Social "&
	if(INCLUDES(Digital_Products__c, "D-Social New"), "New ", "")&
	if(INCLUDES(Digital_Products__c, "D-Social Pre-Owned"),"Pre-Owned ", "")&
	if(INCLUDES(Digital_Products__c, "D-Social Service"), "Service", "")
	&BR(), ""
  )&

  if(  INCLUDES(Digital_Products__c, "D-Advid New") || INCLUDES(Digital_Products__c, "D-Advid Pre-Owned"), 
    "Advid "&
	if(INCLUDES(Digital_Products__c, "D-Advid New"), "New ", "")&
	if(INCLUDES(Digital_Products__c, "D-Advid Pre-Owned"),"Pre-Owned ", "")
	&BR(), ""
  )&

  if(  INCLUDES(Digital_Products__c, "D-OTT Dynamic") || INCLUDES(Digital_Products__c, "D-OTT Custom"), 
    "OTT "&
	if(INCLUDES(Digital_Products__c, "D-OTT Dynamic"), "Dynamic ", "")&
	if(INCLUDES(Digital_Products__c, "D-OTT Custom"),"Custom", "")
	&BR(), ""
  )
)
